from pathlib import Path
from collections.abc import Iterator

def read_errors(path: Path) -> Iterator[str]:
    with path.open(encoding="utf-8") as stream:
        for line in stream:  # une ligne à la fois, jamais tout le fichier en mémoire
            if "ERROR" in line:
                yield line.rstrip("\n")

def first_n_errors(path: Path, n: int) -> list[str]:
    errors = read_errors(path)
    return [next(errors) for _ in range(n)]  # arrêt anticipé, évaluation paresseuse
